-- تولید ۴۵ روز اخیر (۱۲ اینورتر) — به‌صورت رویه‌ای تولید می‌شود
select 'c5010000-0000-4000-8000-000000000001', i.id, i.name, d::date,
  greatest(0, round((i.capacity_kw * 4.9 * (0.80 + 0.03*sin(extract(doy from d)/12.0))
     * (case when extract(day from d)::int % 11 = 0 then 0.55 when extract(day from d)::int % 7 = 0 then 0.82 else 1 end))::numeric, 0)),
  round((i.capacity_kw * 0.72)::numeric, 0), 9.4,
  round((6.4*(0.96+0.04*sin(extract(doy from d)/12.0)))::numeric, 2),
  round((30+6*sin(extract(doy from d)/8.0))::numeric, 0), 'داده نمونه'
from solar_inverters i
cross join generate_series(current_date - interval '44 day', current_date, interval '1 day') as d
where i.project_id = 'c5010000-0000-4000-8000-000000000001'
  and i.status = 'active'
  and not exists (select 1 from solar_generation where project_id = 'c5010000-0000-4000-8000-000000000001');

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;


-- ================================================================
--  نیروگاه سیکل ترکیبی CHP نمونه (کامل)
-- ================================================================
on conflict (id) do nothing;

on conflict (id) do nothing;

-- تولید ۳۰ روز اخیر (۳ ژنراتور) — برق، حرارت و گاز
select 'c6010000-0000-4000-8000-000000000001', u.id, u.name, d::date,
  round((u.elec_capacity_kw * 22 * (0.95 + 0.04*sin(extract(doy from d)/10.0)))::numeric, 0),
  round((u.thermal_capacity_kw * 18)::numeric, 0),
  round((u.elec_capacity_kw * 22 / 4.2)::numeric, 0), 0, 22, 'داده نمونه'
from chp_units u
cross join generate_series(current_date - interval '29 day', current_date, interval '1 day') as d
where u.project_id = 'c6010000-0000-4000-8000-000000000001'
  and not exists (select 1 from chp_generation where project_id = 'c6010000-0000-4000-8000-000000000001');

on conflict (id) do nothing;

